  async function fetchAssessmentHistory(userId, limit = 500) {
    if (!sb || !userId) return [];
    // Sept 10 2026, round 6 — assessed_on is a DATE column (no time of
    // day), so with only that as the sort key, any two rows logged on the
    // same calendar date come back in whatever order Postgres feels like
    // for a tie — not necessarily insertion order. This session's rapid
    // repeat-testing left several same-day auto-recalculated rows on file
    // for more than one client, and "latest row" picked out of those ties
    // was genuinely non-deterministic (see recalcBmrAndTargets and
    // fetchLatestDisplayAssessment below for the real fix to how BMR gets
    // shown). id is a secondary sort key here purely so this list itself
    // is at least stable/deterministic across re-fetches.
    const { data } = await sb.from("body_assessments").select("*")
      .eq("user_id", userId).order("assessed_on", { ascending: false }).order("id", { ascending: false }).limit(limit);
    return data || [];
  }

