    // row at all for the common case. A REAL manually-entered BMR (typed
    // in on the Assessments form — smart scale, DEXA scan) still always
    // wins, exactly as Jimmy asked. Otherwise, whenever the caller has the
    // client's current profile stats on hand, BMR is computed LIVE right
    // here, directly from those stats — not read back from any row — so
    // there is no "which row is newest" question left to get wrong. Editing
    // weight in Edit Profile now can't help but move this number, because
    // it no longer goes through the database to get here.
    const hasManualBmr = latestManual && latestManual.bmr != null;
    let bmr = null, leanMassKg = null;
